DROP TABLE IF EXISTS `Invoices`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Invoices` (
  `InvoiceID` int NOT NULL AUTO_INCREMENT,
  `OrderID` int NOT NULL,
  `InvoiceDate` datetime DEFAULT NULL,
  `SubTotal` decimal(12,4) NOT NULL DEFAULT '0.0000',
  `TaxRate` decimal(5,4) NOT NULL DEFAULT '0.1900',
  `TaxAmount` decimal(12,4) NOT NULL DEFAULT '0.0000',
  `TotalAmount` decimal(12,4) NOT NULL DEFAULT '0.0000',
  PRIMARY KEY (`InvoiceID`),
  KEY `IX_Invoices_OrderID` (`OrderID`),
  CONSTRAINT `FK_Invoices_Orders` FOREIGN KEY (`OrderID`) REFERENCES `Orders` (`OrderID`)
) ENGINE=InnoDB AUTO_INCREMENT=1024 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

